NAME = 'GerZurcher: Deutsche Zürcher Bibel von 1931.'
BOOK = 'Habakkuk'

CHAPTERS = {
    1: {
        1: 'DER Ausspruch, den der Prophet Habakuk (in einem Gesichte) geschaut hat.',
        2: 'Wie lange schon rufe ich, Herr, und du hörst nicht! schreie ich zu dir über Gewalt, und du kommst nicht zu Hilfe!',
        3: 'Warum lässest du mich Unrecht sehen und muss ich Unheil schauen? warum ist Bedrückung und Gewalttat vor meinen Augen und Streit und Hader?',
        4: 'Darum erschlafft das Gesetz, und das Recht kommt nimmermehr auf; denn der Gottlose umringt den Gerechten, und das Recht wird verkehrt.',
        5: 'Seht hin unter die Völker und schaut, starret und staunt! Denn ich tue ein Werk in euren Tagen - ihr glaubtet es nicht, würde es erzählt.',
        6: 'Denn siehe, ich erwecke die Chaldäer, das grausame, ungestüme Volk, das in die Fernen der Erde zieht, Wohnungen einzunehmen, die nicht sein sind.',
        7: 'Schrecklich und furchtbar ist es. Von ihm geht das Gericht aus.',
        8: 'Schneller als Panther sind seine Rosse, und seine Reiter grimmiger als Wölfe am Abend; von fernher kommen sie geflogen wie der Adler, der zum Frasse eilt. (a) 5Mo 28:49',
        9: 'Sie kommen alle, Gewalt zu üben, ihr Angesicht richtend wider den Osten, und sammeln Gefangene wie Sand.',
        10: 'Sie spotten der Könige, und Fürsten sind ihnen ein Gelächter; sie lachen jeder Feste, schütten Erde auf und nehmen sie ein.',
        11: 'Dann wirbeln sie dahin wie der Wind und ziehen weiter und machen ihre Kraft zu ihrem Gott.',
        12: 'Bist nicht du, o Herr, von Urzeit her mein heiliger Gott? Wir werden nicht sterben. Herr, du hast sie zum Gerichte bestellt und als Boten zur Strafe verordnet. (a) Jes 10:5',
        13: 'Deine Augen sind zu rein, als dass sie Böses ansehen könnten, und dem Argen vermagst du nicht zuzuschauen. Warum siehst du denn den Treulosen zu und schweigst, wenn der Gottlose den Gerechten verschlingt, (a) Ps 5:5',
        14: 'wenn er den Menschen tut wie den Fischen im Meer, wie dem Gewürm, das keinen Herrscher hat?',
        15: 'Alles holt er mit der Angel herauf, schleppt es mit seinem Netz und sammelt es in seinem Garn; darob freut er sich und frohlockt.',
        16: 'Darum opfert er seinem Netze und räuchert seinem Garn; denn durch sie wird ihm sein reichlich Teil und ein fettes Mahl.',
        17: 'Soll er denn ewig sein Schwert zücken und ohne Unterlass die Völker schonungslos würgen?',
    },
    2: {
        1: 'AUF meine Warte will ich treten, auf den Turm mich stellen, will spähen und schauen, was er mit mir reden und was er antworten wird auf meinen Vorhalt. (a) Jes 21:8; Hes 33:7',
        2: 'Da antwortete mir der Herr und sprach: Schreibe die Offenbarung nieder und grabe sie ein auf Tafeln, dass man sie geläufig lesen kann. (a) Jes 30:8',
        3: 'Denn noch ist der Offenbarung ihre Frist gesetzt, doch sie drängt zum Ende und trügt nicht. Wenn sie verzieht, so harre darauf! Denn sie kommt gewiss und bleibt nicht aus. (a) 2Pe 3:9',
        4: '"Siehe, der Ungerechte - seine Seele verschmachtet in ihm; der Gerechte aber wird kraft seiner Treue (gegen Gott) am Leben bleiben." (a) Rö 1:17; Ga 3:11; Heb 10:38',
        5: 'Wehe dem treulosen Verächter, dem stolzen Mann, der nie genug hat, der seinen gierigen Schlund weit aufsperrt wie die Unterwelt und unersättlich ist wie der Tod, der zu sich sammelt alle Völker und um sich vereinigt alle Nationen!',
        6: 'Werden sie nicht alle einen Spruch über ihn anheben, im Hohngedicht auf ihn anspielen und sprechen: Wehe dem, der aufhäuft, was nicht sein ist - wie lange noch? - und schwere Schuldenlast sich auflädt!',
        7: 'Werden nicht plötzlich deine Gläubiger aufstehen und deine Peiniger erwachen, dass du ihnen zum Raube wirst?',
        8: 'Weil du viele Völker ausgeraubt hast, werden die übrigen Völker alle dich ausrauben um der Blutschuld an den Menschen willen und wegen der Gewalttat an der Erde, an der Stadt und allen, die darin wohnen. (a) Jes 33:1',
        9: 'Wehe dem, der bösen Gewinn einheimst in sein Haus, um in der Höhe sein Nest zu bauen, um sich zu retten aus der Hand des Unheils!',
        10: 'Du hast beschlossen, was deinem Hause Schande bringt: viele Völker hast du vernichtet, deiner eignen Seele zur Sünde.',
        11: 'Ja, der Stein in der Mauer schreit, und der Balken im Holzwerk antwortet ihm. (a) Lu 19:40',
        12: 'Wehe dem, der eine Stadt mit Blut baut und eine Burg auf Unrecht gründet! (a) Mi 3:10',
        13: 'Kommt nicht vom Herrn der Heerscharen das Wort: "Völker arbeiten fürs Feuer, und Nationen mühen sich ab für nichts"? (a) Jer 51:58',
        14: 'Denn die Erde wird voll werden der Erkenntnis der Herrlichkeit des Herrn, wie das Meer von Wassern bedeckt ist. (a) Jes 11:9',
        15: 'Wehe dem, der den andern seinen Zorn zu trinken gibt und aus der Schale seines Grimms sie berauscht, um ihre Blösse zu schauen! (a) Jes 51:17',
        16: 'So trinke nun auch du und taumle! An dich kommt nun der Becher in der Rechten des Herrn; du sollst satt werden an Schmach statt an Ehre. (a) Jer 25:15-31',
        17: 'Denn der Frevel am Libanon wird auf dir lasten, und die Vernichtung der Tiere wird dich erdrücken um der Blutschuld an den Menschen willen und wegen der Gewalttat an der Erde, an der Stadt und allen, die darin wohnen. (a) Jes 14:8; 37:24',
        18: 'Was hilft denn das Schnitzbild, dass der Meister es schnitzt, das Gussbild und Lügenorakel, dass der Meister darauf vertraut und stumme Götzen macht? (1) V. 18-20: Versreihenfolge in Originalüs: 19, 18, 20. (a) Jes 44:10',
        19: 'Wehe dem, der zum Holz spricht: "Erwache!" und zum stummen Stein: "Stehe auf!" Dergleichen sollte weissagen? Es ist ja gefasst in Silber und Gold, und keinerlei Odem ist in ihm.',
        20: 'Aber der Herr ist in seinem heiligen Tempel - stille vor ihm, alle Welt! (a) Ps 11:4; Zef 1:7; Sac 2:13',
    },
    3: {
        1: 'GEBET des Propheten Habakuk.',
        2: 'O Herr, ich habe Kunde von dir vernommen, habe dein Tun geschaut, o Herr! Inmitten der Jahre lass es werden, inmitten der Jahre tue dich kund, im Zorn sei eingedenk des Erbarmens!',
        3: 'Gott kommt von Theman her, der Heilige vom Gebirge Paran. Seine Hoheit bedeckt den Himmel, und die Erde ist voll seines Ruhmes. (a) 5Mo 33:2',
        4: 'Sein Glanz erscheint wie das Licht, Strahlen ihm zur Seite; er macht sie zur Hülle seiner Herrlichkeit.',
        5: 'Vor ihm her geht die Pest, und die Seuche folgt ihm auf dem Fuss. (a) 2Mo 9:3; 2Sa 24:15',
        6: 'Er tritt auf und macht die Erde erbeben, er schaut hin und macht die Völker auffahren. Es zerbersten die ewigen Berge, es versinken die Hügel der Vorzeit, seine ewigen Bahnen. (a) Ps 68:9',
        7: 'Dem Unheil verfallen sehe ich die Zelte Kusans, es erbeben die Zeltdecken Midians.',
        8: 'Ist über die Ströme dein Zorn entbrannt, o Herr, oder dein Grimm über das Meer, dass du darüber fährst auf deinen Rossen, auf deinen Siegeswagen? (a) Ps 68:18; Jes 66:15',
        9: 'Gänzlich enthüllst du den Bogen, gesättigt mit Geschossen ist dein Köcher. Du spaltest die Erde - da fliessen Ströme;',
        10: 'die Berge sehen dich und erbeben. Wasser giessen die Wolken, der Ozean erhebt seine Stimme. Ihres Aufgangs vergisst',
        11: 'die Sonne, der Mond bleibt in seiner Wohnung beim Licht deiner fliegenden Pfeile, beim Glanz deines blitzenden Speers.',
        12: 'Im Grimme schreitest du über die Erde, im Zorn zertrittst du Nationen.',
        13: 'Du ziehst aus, deinem Volk zu Hilfe, zu helfen deinem Gesalbten. Du schmetterst das Dach weg vom Hause des Gottlosen, legst den Grund bloss bis auf den Fels.',
        14: 'Du durchbohrst mit deinen Geschossen sein Haupt, seine Fürsten werden verweht wie Spreu. Mich zu zerstreuen, ziehen heran ihre Scharen, den Armen im Versteck zu verschlingen.',
        15: 'Du lässest deine Rosse fahren über das Meer, da brausen die grossen Wasser.',
        16: 'Ich hörte es, und es bebte mein Leib; ob des Schalls gellte mein Mund. Der Frass drang in meine Gebeine, und unter mir bebte mein Schritt. Ich werde Ruhe finden am Tage der Drangsal, der hereinbrechen wird über das Volk, das mich bedrängt.',
        17: 'Denn der Feigenbaum trägt nicht, und an den Reben ist kein Ertrag; es schlägt fehl die Frucht des Ölbaums, und der Acker bringt kein Brot; die Schafe sind aus der Hürde verschwunden, und in den Ställen steht kein Rind mehr.',
        18: 'Ich aber will ob dem Herrn frohlocken, will jubeln ob dem Gott meines Heils.',
        19: 'Gott der Herr ist meine Kraft! Er macht meine Füsse den Hinden gleich und lässt mich auf Höhen schreiten. (a) Ps 18:34',
    },
}
